"""Zoo 1.114.1: the floor hatch's yellow frame paints on a tintable pack, so it reads yellow.

FOUND by cold run 9343 (precinct_yard_001, the first package with a floor hatch in it; roadmap 265): the floor form's
safety-yellow 3 cm frame read dark brown (`docs/cold_runs/cold_9343/`). The yellow rides in the frame's vertex colours
and multiplies into the pack's albedo, and the recipe painted the form with the slot's own `metal`, which the theme's
skin library resolves to rusted street steel -- not tintable, mean sRGB (0.451, 0.315, 0.208). `FLOOR_PAINT =
"metal_painted"`, a tintable neutral pack (mean 0.93), whatever the slot's material. A/B on the real build path
(`zoo_cli.py --build-kit` on the one hatch slot, with 9343's own skins): 1.114.0 reproduces the shipped module's
`M_Skin_metal_delco` on the rust texture; 1.114.1 builds `M_Skin_metal_painted_delco_ffffff` on the painted neutral
one, the yellow still in the vertex colours, two materials either way (`patches/zoo_hatch_paint/hatch_ab/`).

What it changes (anchored; each file pinned by the hash of its LF text; nothing written on a miss):
  * zoo_keeper/recipes/roof_hatch.py -- `FLOOR_PAINT`, and the floor branch's `make_material` takes it.
  * tests/test_hole_forms.py -- `test_the_floor_form_paints_on_a_tintable_kind_never_the_slots_material` (fails on
    1.114.0, `patches/zoo_hatch_paint/prove_tests_on_11140.out.txt`).
  * VERSION 1.114.0 -> 1.114.1, CHANGELOG.

Generated by `patches/zoo_hatch_paint/gen_zoo_hatch_paint.py` from a proven clone; its dry runs, the suite and the
prove run are beside it.

    python patches/patch_zoo_hatch_paint.py
"""
import hashlib
import pathlib
import sys

ROOT = pathlib.Path(__file__).resolve().parents[1]
REPO = ROOT / "zoo"
PINS = {'zoo_keeper/recipes/roof_hatch.py': 'a2f0c5b0946cfaff', 'tests/test_hole_forms.py': '2c1b0e7e92c969ed'}
EDITS = {'zoo_keeper/recipes/roof_hatch.py': [('lines 42-41', 'SAFETY_YELLOW = (0.86, 0.64, 0.04)\n\n', 'SAFETY_YELLOW = (0.86, 0.64, 0.04)\n#: The floor form\'s paint kind, whatever the slot\'s material (1.114.1): a TINTABLE pack, an achromatic grain the\n#: mesh\'s colours multiply into. Cold run 9343 shipped the frame dark brown: the slot\'s `metal` resolves to the\n#: theme\'s rusted street steel, which Pixelcoat declares not tintable (mean sRGB 0.45, 0.32, 0.21), and safety\n#: yellow times rust is brown. `metal_painted` is tintable (mean 0.93), as the CRT cabinet and the containers take it.\nFLOOR_PAINT = "metal_painted"\n\n'), ('lines 137-136', '    # colour rides in `Wear` (`geometry.tint_wear`), the draw-call rule for colour-only variation.\n    floor = (plan.get("params") or {}).get("form") == "floor"\n', '    # colour rides in `Wear` (`geometry.tint_wear`), the draw-call rule for colour-only variation.\n    # The white is FLOOR_PAINT\'s, never the slot\'s material (1.114.1): a colour can only ride a\n    # tintable pack, and the slot\'s `metal` is rust.\n    floor = (plan.get("params") or {}).get("form") == "floor"\n'), ('lines 142-142', '            f"M_RoofHatch_{plan[\'material\']}_floor", [1.0, 1.0, 1.0], plan["material"])\n', '            f"M_RoofHatch_{FLOOR_PAINT}_floor", [1.0, 1.0, 1.0], FLOOR_PAINT)\n')], 'tests/test_hole_forms.py': [('lines 191-190', '\ndef test_a_roof_hatch_slot_without_a_form_plans_as_it_always_did():\n', '\ndef test_the_floor_form_paints_on_a_tintable_kind_never_the_slots_material():\n    """Cold run 9343 (the factory\'s roadmap 265): the floor hatch\'s safety-yellow frame shipped dark brown. The\n    yellow rides in the frame\'s vertex colours (`geometry.tint_wear`) and multiplies into the pack\'s albedo, and the\n    slot\'s `metal` resolves to the theme\'s rusted street steel -- Pixelcoat declares that pack not tintable, mean sRGB\n    (0.45, 0.32, 0.21) -- so yellow times rust read brown. The floor form paints on `metal_painted`, which Pixelcoat\n    declares tintable (a near-white grain, mean 0.93), whatever material the slot carries. Read off the recipe\'s\n    source, because a recipe imports Blender\'s layer."""\n    import ast\n    import os\n\n    path = os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))),\n                        "zoo_keeper", "recipes", "roof_hatch.py")\n    tree = ast.parse(open(path, encoding="utf-8").read())\n    consts = {t.id: n.value.value for n in tree.body if isinstance(n, ast.Assign)\n              for t in n.targets if isinstance(t, ast.Name) and isinstance(n.value, ast.Constant)}\n    assert consts.get("FLOOR_PAINT") == "metal_painted", consts.get("FLOOR_PAINT")\n    build = next(n for n in tree.body if isinstance(n, ast.FunctionDef) and n.name == "build")\n    branch = next(n for n in ast.walk(build) if isinstance(n, ast.If)\n                  and isinstance(n.test, ast.Name) and n.test.id == "floor")\n    calls = [c for stmt in branch.body for c in ast.walk(stmt)\n             if isinstance(c, ast.Call) and getattr(c.func, "attr", "") == "make_material"]\n    assert len(calls) == 1, [ast.dump(c) for c in calls]\n    kind = calls[0].args[2]\n    assert isinstance(kind, ast.Name) and kind.id == "FLOOR_PAINT", ast.dump(kind)\n    # the colour is the mesh\'s: the paint itself stays white\n    assert [ast.literal_eval(v) for v in calls[0].args[1].elts] == [1.0, 1.0, 1.0]\n\n\ndef test_a_roof_hatch_slot_without_a_form_plans_as_it_always_did():\n')]}
NEW_FILES = {}
CHANGELOG = '## [1.114.1] - the floor hatch\'s yellow frame paints on a tintable pack, so it reads yellow\n\n**Found by the factory\'s cold run 9343** (precinct_yard_001, the first package with a floor hatch in it; roadmap 265).\n1.114.0\'s floor form paints its 3 cm frame safety yellow so the opening reads from across a room, and in the frame\nit read dark brown. Measured on the shipped module, `prop_roof_hatch_delco_04_w166_d166_h3_ffloor.glb`: the yellow\nis there, (0.863, 0.638, 0.040) in the frame\'s vertex colours, and Level Factory\'s worldskin draws them; but the\nrecipe painted the form with the slot\'s own material, `metal`, and the theme\'s `metal` pack is rusted street steel,\nwhich Pixelcoat declares not tintable -- one material per theme, `M_Skin_metal_delco`, its albedo mean sRGB (0.451,\n0.315, 0.208). Yellow times rust lands near (0.39, 0.20, 0.01). The hinge, on `metal_bare`, took the neutral pack.\n\n### Fixed\n- `recipes/roof_hatch.py`: `FLOOR_PAINT = "metal_painted"`, the floor form\'s paint kind whatever the slot\'s\n  material -- a tintable pack, an achromatic grain (mean 0.93 on the same run) the mesh\'s colours multiply into, as\n  the CRT cabinet and the containers take it. The frame\'s yellow and the lid\'s grey still ride in the vertex\n  colours; still one material and the hinge\'s, two submissions. The roof form is unchanged.\n\n### Tests\n- `test_hole_forms.py`: `test_the_floor_form_paints_on_a_tintable_kind_never_the_slots_material` (602 in the file;\n  fails on 1.114.0), read off the recipe\'s source because a recipe imports Blender\'s layer.\n\n'
OLD_VERSION, NEW_VERSION = '1.114.0', '1.114.1'


def _sha(b):
    return hashlib.sha256(b).hexdigest()[:16]


def _read(name):
    """The file's LF text and whether it is CRLF on disk; refuses mixed endings and a file that is not the pinned one."""
    raw = (REPO / name).read_bytes()
    crlf, lf = raw.count(b"\r\n"), raw.count(b"\n")
    if crlf not in (0, lf):
        raise SystemExit("REFUSED: zoo/%s has mixed line endings (%d CRLF of %d); nothing written"
                         % (name, crlf, lf))
    text = raw.decode("utf-8").replace("\r\n", "\n")
    if _sha(text.encode("utf-8")) != PINS[name]:
        raise SystemExit("REFUSED: zoo/%s is %s, not the %s this patch was written against; nothing "
                         "written" % (name, _sha(text.encode("utf-8")), PINS[name]))
    return text, crlf > 0


def main(argv):
    # every file worked out and checked before any is written
    out = {}
    for name, edits in EDITS.items():
        text, crlf = _read(name)
        for what, old, new in edits:
            if text.count(old) != 1:
                raise SystemExit("REFUSED: zoo/%s: the anchor at %s is there %d times; nothing written"
                                 % (name, what, text.count(old)))
            text = text.replace(old, new)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name in NEW_FILES:
        if (REPO / name).exists():
            raise SystemExit("REFUSED: zoo/%s exists already; nothing written" % name)
    v = REPO / "VERSION"
    if v.read_bytes().decode("utf-8") != OLD_VERSION:
        raise SystemExit("REFUSED: VERSION reads %r, not %s; nothing written" % (v.read_text(), OLD_VERSION))
    cl = REPO / "CHANGELOG.md"
    craw = cl.read_bytes()
    if b"\r\n" in craw or not craw.startswith(b"## [" + OLD_VERSION.encode() + b"]"):
        raise SystemExit("REFUSED: CHANGELOG.md is not LF opening on %s; nothing written" % OLD_VERSION)
    for name, text in out.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    for name, text in NEW_FILES.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    v.write_bytes(NEW_VERSION.encode("utf-8"))
    cl.write_bytes(CHANGELOG.encode("utf-8") + craw)
    print("Zoo %s applied: %d files edited, %d written, VERSION, CHANGELOG. Now, in zoo/: the "
          "suite" % (NEW_VERSION, len(out), len(NEW_FILES)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
